<template>
  <div class="type-library wb-page"><div class="wb-page__inner">
    <PageHeader eyebrow="教学资源 / 数学周末课" title="我的题型库" description="系统会按近期错题自动归到知识点下；你只需确认要讲的题型，再生成周末课讲义。"><template #actions><ActionButton :loading="organizing" @click="autoOrganize"><el-icon><Refresh /></el-icon>更新本周整理</ActionButton><ActionButton variant="primary" :loading="handoutBuilding" @click="buildWeekendHandout"><el-icon><Reading /></el-icon>生成周末讲义初稿</ActionButton></template></PageHeader>
    <section class="library-stats"><div class="library-stat primary"><span>待你确认</span><strong>{{ summary.recommendation_count || 0 }}</strong><small>系统按近期错题自动整理</small></div><div class="library-stat"><span>已沉淀题型</span><strong>{{ summary.type_count || 0 }}</strong><small>覆盖 {{ summary.knowledge_count || 0 }} 个知识点</small></div><div class="library-stat"><span>本周维护</span><strong>{{ summary.updated_this_week || 0 }}</strong><small>讲义会使用独立内容快照</small></div></section>
    <ContentCard class="automation-guide" flush><div class="guide-copy"><span class="guide-step">1</span><div><strong>先看系统整理</strong><small>基于近期错题的主知识点、错误人数和典型代表题自动分组。</small></div></div><div class="guide-copy"><span class="guide-step">2</span><div><strong>确认值得讲的题型</strong><small>保留、编辑或忽略；不会修改任何学生的错题和掌握度。</small></div></div><div class="guide-copy"><span class="guide-step">3</span><div><strong>生成周末课初稿</strong><small>按“知识点 → 题型 → 代表题”自动编排，再进入讲义调整。</small></div></div></ContentCard>
    <FilterBar class="type-filter"><template #leading><div class="result-context"><strong>{{ activeMode === 'recommended' ? '本周自动整理' : '已确认题型库' }}</strong><span>{{ types.length }} 个题型</span></div></template><el-button-group><el-button :type="activeMode === 'recommended' ? 'primary' : ''" @click="setMode('recommended')">待确认</el-button><el-button :type="activeMode === 'library' ? 'primary' : ''" @click="setMode('library')">已确认</el-button></el-button-group><WorkbenchInput v-model="keyword" clearable placeholder="搜索题型或讲法" width="240px" aria-label="搜索题型或讲法" @input="debouncedLoad"><template #prefix><el-icon><Search /></el-icon></template></WorkbenchInput><WorkbenchSelect v-model="selectedKpId" :options="kpFilterOptions" :filterable="true" clearable placeholder="全部知识点" width="200px" aria-label="按知识点筛选" @change="loadTypes" /><template #actions><el-button text @click="startCreate"><el-icon><Plus /></el-icon>手动补充</el-button></template></FilterBar>
    <main class="library-workspace"><ContentCard class="type-list-card" title="题型清单" :description="activeMode === 'recommended' ? '优先确认近期高频、多人出错的题型' : '长期可复用的教学题型'" flush><div v-if="loading" class="list-loading"><el-skeleton v-for="index in 6" :key="index" animated :rows="2" /></div><EmptyState v-else-if="!types.length" :icon="activeMode === 'recommended' ? CircleCheck : Collection" :title="activeMode === 'recommended' ? '本周没有待确认题型' : '还没有已确认题型'" :description="activeMode === 'recommended' ? '可以更新本周整理，或近期错题尚未完成知识点关联。' : '先确认系统整理的题型，或手动补充一个教学题型。'"><template #actions><ActionButton v-if="activeMode === 'recommended'" @click="autoOrganize">更新本周整理</ActionButton><ActionButton v-else variant="primary" @click="startCreate">手动补充题型</ActionButton></template></EmptyState><div v-else class="type-list"><button v-for="item in types" :key="item.id" type="button" :class="['type-row',{active:selectedId===item.id}]" @click="selectType(item.id)"><span class="row-main"><strong>{{ item.name }}</strong><small>{{ item.knowledge_name }} · {{ item.example_count }} 道代表题</small></span><span class="row-evidence" v-if="item.auto_summary?.wrongCount">{{ item.auto_summary.wrongCount }} 次错误<br>{{ item.auto_summary.studentCount }} 名学生</span><el-icon><ArrowRight /></el-icon></button></div></ContentCard>
      <ContentCard class="type-inspector" title="题型详情" :description="selectedType ? `${selectedType.knowledge_name} · ${selectedType.status === 'draft' ? '系统建议，等待确认' : '已确认教学资产'}` : '选择一个题型查看详情'" flush><div v-if="detailLoading" class="detail-loading"><el-skeleton animated :rows="10" /></div><EmptyState v-else-if="!selectedType" :icon="Reading" title="选择一个题型" description="右侧会展示系统依据、讲解建议和代表题。" compact /><article v-else class="type-detail"><div class="detail-heading"><div><div class="knowledge-label">{{ selectedType.knowledge_name }}</div><h2>{{ selectedType.name }}</h2></div><el-dropdown @command="handleDetailAction"><el-button text aria-label="题型操作"><el-icon><MoreFilled /></el-icon></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="edit">编辑题型</el-dropdown-item><el-dropdown-item command="ignore" v-if="selectedType.status==='draft'" divided>忽略本次建议</el-dropdown-item><el-dropdown-item command="archive" v-else divided>归档题型</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div><div class="recommendation" v-if="selectedType.status==='draft'"><strong>系统建议</strong><span>近 {{ selectedType.auto_summary?.days || 14 }} 天内，{{ selectedType.auto_summary?.studentCount || 0 }} 名学生出现 {{ selectedType.auto_summary?.wrongCount || 0 }} 次相关错误。</span></div><div v-if="selectedType.tags?.length" class="detail-tags"><el-tag v-for="tag in selectedType.tags" :key="tag" size="small">{{tag}}</el-tag></div><section class="detail-section"><h3>建议课堂讲法</h3><p>{{selectedType.teaching_notes || '暂未生成讲法。'}}</p></section><section class="detail-section"><h3>典型易错点</h3><p>{{selectedType.common_mistakes || '暂未收集到明确错因。'}}</p></section><section class="detail-section examples"><div class="section-heading"><h3>代表题</h3><span>{{selectedType.examples?.length || 0}} 道</span></div><article v-for="example in selectedType.examples" :key="example.id" class="example-card"><div class="example-content">{{example.snapshot?.content || '题目内容快照不可用'}}</div><div class="example-meta"><span>{{example.snapshot?.questionType || '综合题'}}</span><span v-if="example.snapshot?.answer">答案：{{example.snapshot.answer}}</span></div><el-button v-if="example.sourceQuestionId" text size="small" :loading="variantLoadingId===example.id" @click="generateVariants(example)">生成变式练习</el-button></article></section><div class="detail-actions" v-if="selectedType.status==='draft'"><el-button @click="editSelected">先修改</el-button><el-button type="primary" :loading="confirming" @click="confirmType">确认收录到题型库</el-button></div></article></ContentCard></main>
  </div>
  <el-drawer v-model="editorVisible" :title="editingId ? '编辑题型' : '手动补充题型'" size="min(520px,100%)" destroy-on-close><el-form label-position="top" :model="editor"><el-form-item label="主知识点" required><WorkbenchSelect v-model="editor.kpId" :options="editorKpOptions" :filterable="true" placeholder="选择主知识点" aria-label="选择主知识点" /></el-form-item><el-form-item label="题型名称" required><WorkbenchInput v-model="editor.name" :maxlength="60" show-word-limit placeholder="如：相似三角形判定" aria-label="题型名称" /></el-form-item><el-form-item label="课堂讲法"><WorkbenchInput v-model="editor.teachingNotes" type="textarea" :rows="5" placeholder="记录课堂讲法，便于复用" aria-label="课堂讲法" /></el-form-item><el-form-item label="易错提醒"><WorkbenchInput v-model="editor.commonMistakes" type="textarea" :rows="3" placeholder="学生常见错误与应对" aria-label="易错提醒" /></el-form-item><el-form-item label="教学标签"><el-select v-model="editor.tags" multiple filterable allow-create class="wb-select" style="width:100%" placeholder="输入后回车添加" aria-label="教学标签" /></el-form-item></el-form><template #footer><div class="drawer-actions"><el-button @click="editorVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveType">保存</el-button></div></template></el-drawer>
  </div>
</template>
<script setup>
import {computed,onMounted,ref} from 'vue'
import {useRouter} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import {ArrowRight,CircleCheck,Collection,MoreFilled,Plus,Reading,Refresh,Search} from '@element-plus/icons-vue'
import {apiRequest,getKnowledgeTree} from '../../services/apiService'
import ActionButton from '../components/ui/ActionButton.vue'; import ContentCard from '../components/ui/ContentCard.vue'; import EmptyState from '../components/ui/EmptyState.vue'; import FilterBar from '../components/ui/FilterBar.vue'; import PageHeader from '../components/ui/PageHeader.vue'; import WorkbenchInput from '../components/ui/WorkbenchInput.vue'; import WorkbenchSelect from '../components/ui/WorkbenchSelect.vue'
const router=useRouter(), types=ref([]),summary=ref({}),tree=ref([]),activeMode=ref('recommended'),selectedKpId=ref(null),keyword=ref(''),selectedId=ref(null),selectedType=ref(null),loading=ref(false),detailLoading=ref(false),organizing=ref(false),handoutBuilding=ref(false),confirming=ref(false),saving=ref(false),variantLoadingId=ref(null),editorVisible=ref(false),editingId=ref(null)
const blankEditor=()=>({kpId:selectedKpId.value||'',name:'',teachingNotes:'',commonMistakes:'',tags:[]}); const editor=ref(blankEditor()); const flatten=(nodes,out=[])=>{for(const node of nodes||[]){out.push(node);flatten(node.children,out)}return out}; const flatKnowledge=computed(()=>flatten(tree.value)); const kpFilterOptions=computed(()=>[{label:'全部知识点',value:null},...flatKnowledge.value.map(kp=>({label:'　'.repeat(kp.level||0)+kp.name,value:kp.id}))]); const editorKpOptions=computed(()=>flatKnowledge.value.map(kp=>({label:'　'.repeat(kp.level||0)+kp.name,value:kp.id}))); let timer; const debouncedLoad=()=>{clearTimeout(timer);timer=setTimeout(loadTypes,250)}
async function loadTypes(){loading.value=true;try{const params=new URLSearchParams({mode:activeMode.value});if(selectedKpId.value)params.set('kpId',selectedKpId.value);if(keyword.value)params.set('keyword',keyword.value);const data=await apiRequest(`/teaching-question-types?${params}`);types.value=data.types||[];if(selectedId.value&&!types.value.some(item=>item.id===selectedId.value)){selectedId.value=null;selectedType.value=null}}catch(error){ElMessage.error(error.message||'加载题型失败')}finally{loading.value=false}}
async function loadSummary(){const data=await apiRequest('/teaching-question-types/summary');summary.value=data.summary||{}} async function selectType(id){selectedId.value=id;detailLoading.value=true;try{const data=await apiRequest(`/teaching-question-types/${id}`);selectedType.value=data.type}catch(error){ElMessage.error(error.message||'加载详情失败')}finally{detailLoading.value=false}} function setMode(mode){activeMode.value=mode;selectedId.value=null;selectedType.value=null;loadTypes()}
async function autoOrganize(silent=false){organizing.value=true;try{const data=await apiRequest('/teaching-question-types/auto-organize',{method:'POST',body:JSON.stringify({days:14})});if(!silent)ElMessage.success(data.message||'本周整理已更新');activeMode.value='recommended';await Promise.all([loadTypes(),loadSummary()])}catch(error){const message=/404/.test(String(error.message))?'题型库后端尚未更新，请在 Render 重新部署最新 main 后重试':(error.message||'自动整理失败');if(!silent)ElMessage.error(message);else console.warn(message)}finally{organizing.value=false}}
async function buildWeekendHandout(){handoutBuilding.value=true;try{const data=await apiRequest('/teaching-question-types/auto-handout',{method:'POST',body:JSON.stringify({limit:8})});if(!data.handout)return ElMessage.warning(data.message||'暂无可生成的题型');router.push({name:'HandoutPreview',query:{data:encodeURIComponent(JSON.stringify(data.handout)),subject:'数学'}})}catch(error){ElMessage.error(error.message||'生成讲义初稿失败')}finally{handoutBuilding.value=false}}
async function confirmType(){confirming.value=true;try{await apiRequest(`/teaching-question-types/${selectedType.value.id}/confirm`,{method:'POST'});ElMessage.success('已收录到长期题型库');selectedType.value.status='active';await Promise.all([loadTypes(),loadSummary()])}catch(error){ElMessage.error(error.message||'确认失败')}finally{confirming.value=false}}
function startCreate(){editingId.value=null;editor.value=blankEditor();editorVisible.value=true} function editSelected(){editingId.value=selectedType.value.id;editor.value={kpId:selectedType.value.kp_id,name:selectedType.value.name,teachingNotes:selectedType.value.teaching_notes,commonMistakes:selectedType.value.common_mistakes,tags:selectedType.value.tags||[]};editorVisible.value=true} async function saveType(){if(!editor.value.kpId||!editor.value.name.trim())return ElMessage.warning('请填写主知识点和题型名称');saving.value=true;try{const payload={kpId:editor.value.kpId,name:editor.value.name,teachingNotes:editor.value.teachingNotes,commonMistakes:editor.value.commonMistakes,tags:editor.value.tags};const data=editingId.value?await apiRequest(`/teaching-question-types/${editingId.value}`,{method:'PUT',body:JSON.stringify(payload)}):await apiRequest('/teaching-question-types',{method:'POST',body:JSON.stringify(payload)});editorVisible.value=false;await Promise.all([loadTypes(),loadSummary()]);await selectType(data.type.id);ElMessage.success('题型已保存')}catch(error){ElMessage.error(error.message||'保存失败')}finally{saving.value=false}}
async function generateVariants(example){variantLoadingId.value=example.id;try{const response=await apiRequest(`/variants/${example.sourceQuestionId}/generate-all`,{method:'POST',body:JSON.stringify({})});ElMessage.success(response.generated?`已生成 ${response.generated} 道变式题`:'变式题已就绪')}catch(error){ElMessage.error(error.message||'生成变式题失败')}finally{variantLoadingId.value=null}} function handleDetailAction(command){if(command==='edit')return editSelected();const isIgnore=command==='ignore';ElMessageBox.confirm(isIgnore?'忽略后本次自动建议将不再展示。':'归档后题型将不再用于讲义插入。',isIgnore?'忽略建议':'归档题型',{type:'warning'}).then(async()=>{await apiRequest(`/teaching-question-types/${selectedType.value.id}${isIgnore?'/ignore':''}`,{method:isIgnore?'POST':'DELETE'});selectedId.value=null;selectedType.value=null;await Promise.all([loadTypes(),loadSummary()]);ElMessage.success(isIgnore?'已忽略本次建议':'题型已归档')}).catch(()=>{})}
onMounted(async()=>{try{tree.value=await getKnowledgeTree('数学')}catch{ElMessage.warning('知识点目录加载失败')}await autoOrganize(true);await Promise.all([loadTypes(),loadSummary()])})
</script>
<style scoped>
.type-library{min-height:100%;background:var(--wb-bg)}.library-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));margin-bottom:16px;border:1px solid var(--wb-border);border-radius:10px;background:var(--wb-bg-card);overflow:hidden}.library-stat{display:grid;gap:4px;padding:16px 20px;border-right:1px solid var(--wb-border-light)}.library-stat:last-child{border-right:0}.library-stat span,.library-stat small{color:var(--wb-text-tertiary);font-size:11px}.library-stat strong{color:var(--wb-text);font-size:21px}.library-stat.primary strong{color:var(--wb-primary)}.automation-guide{display:grid;grid-template-columns:repeat(3,1fr);margin-bottom:16px}.guide-copy{display:flex;gap:10px;padding:16px;border-right:1px solid var(--wb-border-light)}.guide-copy:last-child{border-right:0}.guide-copy div{display:grid;gap:3px}.guide-copy strong{font-size:12px}.guide-copy small{color:var(--wb-text-secondary);font-size:11px;line-height:1.5}.guide-step{display:grid;width:21px;height:21px;place-items:center;flex:0 0 21px;color:var(--wb-primary);font-size:11px;font-weight:700;background:var(--wb-primary-soft);border-radius:50%}.result-context{display:grid;gap:2px}.result-context span{color:var(--wb-text-tertiary);font-size:11px}.library-workspace{display:grid;grid-template-columns:minmax(330px,.78fr) minmax(440px,1.22fr);gap:16px}.type-list-card,.type-inspector{min-height:580px}.list-loading{display:grid;gap:16px;padding:16px}.type-row{display:flex;align-items:center;gap:12px;width:100%;padding:14px 16px;border:0;border-bottom:1px solid var(--wb-border-light);background:transparent;color:inherit;text-align:left;cursor:pointer}.type-row:hover{background:var(--wb-bg-subtle)}.type-row.active{background:var(--wb-primary-soft);box-shadow:inset 3px 0 var(--wb-primary)}.row-main{display:grid;min-width:0;flex:1;gap:4px}.row-main strong{overflow:hidden;font-size:13px;text-overflow:ellipsis;white-space:nowrap}.row-main small,.row-evidence{color:var(--wb-text-tertiary);font-size:11px}.row-evidence{text-align:right;line-height:1.5;white-space:nowrap}.type-detail{padding:18px 20px}.detail-heading,.section-heading,.detail-actions{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.knowledge-label{margin-bottom:5px;color:var(--wb-primary);font-size:11px;font-weight:650}.detail-heading h2{margin:0;font-size:21px}.recommendation{display:grid;gap:4px;margin:16px 0;padding:11px 12px;border:1px solid #dbe4ff;border-radius:8px;color:#42526e;font-size:12px;background:#f7f9ff}.recommendation strong{color:var(--wb-primary)}.detail-tags{display:flex;gap:6px;flex-wrap:wrap;margin:14px 0}.detail-section{padding:17px 0;border-top:1px solid var(--wb-border-light)}.detail-section h3{margin:0 0 8px;font-size:12px}.detail-section p{margin:0;color:var(--wb-text-secondary);font-size:13px;line-height:1.75;white-space:pre-wrap}.examples{display:grid;gap:10px}.example-card{padding:12px;border:1px solid var(--wb-border-light);border-radius:8px;background:var(--wb-bg-subtle)}.example-content{display:-webkit-box;overflow:hidden;font-size:13px;line-height:1.6;-webkit-box-orient:vertical;-webkit-line-clamp:3}.example-meta{display:flex;gap:10px;margin:9px 0;color:var(--wb-text-tertiary);font-size:11px}.detail-actions{padding-top:18px;border-top:1px solid var(--wb-border-light);align-items:center;justify-content:flex-end}.drawer-actions{display:flex;justify-content:flex-end;gap:8px}@media(max-width:900px){.library-workspace{grid-template-columns:1fr}.type-list-card,.type-inspector{min-height:auto}.type-inspector{min-height:440px}}@media(max-width:720px){.library-stats,.automation-guide{grid-template-columns:1fr}.library-stat,.guide-copy{border-right:0;border-bottom:1px solid var(--wb-border-light)}.library-stat:last-child,.guide-copy:last-child{border-bottom:0}.type-filter :deep(.filter-bar__body){align-items:stretch;flex-direction:column}.row-evidence{display:none}}
</style>
